import{_ as e,o as i,c as a,a2 as t}from"./chunks/framework.BZO4qERu.js";const k=JSON.parse('{"title":"Containerd + Kata","description":"","frontmatter":{},"headers":[],"relativePath":"self-hosted/kata-containerd.md","filePath":"self-hosted/kata-containerd.md","lastUpdated":1781675678000}'),n={name:"self-hosted/kata-containerd.md"};function o(h,s,r,l,d,p){return i(),a("div",null,[...s[0]||(s[0]=[t(`<h1 id="containerd-kata" tabindex="-1">Containerd + Kata <a class="header-anchor" href="#containerd-kata" aria-label="Permalink to &quot;Containerd + Kata&quot;">​</a></h1><p>Memoh can run bot workspaces through containerd&#39;s Kata runtime on Linux/KVM hosts. The Memoh workspace API and lifecycle stay the same, while containerd creates each workspace with <code>io.containerd.kata.v2</code>.</p><p>This path is Linux-only. A macOS or Docker Desktop host can validate compose syntax and runc regressions, but it cannot prove that the Kata runtime works.</p><h2 id="what-this-enables" tabindex="-1">What This Enables <a class="header-anchor" href="#what-this-enables" aria-label="Permalink to &quot;What This Enables&quot;">​</a></h2><ul><li><code>[container].backend = &quot;containerd&quot;</code> remains the workspace backend.</li><li><code>[containerd].runtime_type = &quot;io.containerd.kata.v2&quot;</code> selects Kata for bot workspace containers.</li><li>The <code>server-kata</code> image target uses a Debian/glibc runtime because host Kata shims are commonly glibc-linked.</li><li>The compose overrides mount <code>/dev/kvm</code>, the host Kata shim, Kata config, and Kata runtime assets into the Memoh server container.</li></ul><p>Kata is still driven through containerd snapshots in Memoh. CPU and memory limits are hard limits. Storage is saved and reported as a soft limit until VM disk quota or block-device quota support is added.</p><p>Kata workspaces use the bridge TCP listener (<code>BRIDGE_TCP_ADDR=:9090</code>) instead of the Unix socket bridge used by normal containerd workspaces. A Unix socket can appear on the host through the Kata shared filesystem, but it is not a usable connection boundary across the guest VM. Memoh routes Kata bridge traffic to the workspace CNI IP and disables HTTP proxy use for bridge gRPC dials so proxy settings on the server container do not intercept private workspace addresses.</p><p>For shared deployments, enable <code>[bridge_tls].mode = &quot;strict&quot;</code>. The default <code>disabled</code> mode keeps local installs simple, but it does not protect a shared Kata/CNI network from workspace-to-workspace bridge traffic. In a multi-tenant Kata deployment, strict bridge mTLS is the required isolation layer unless your networking stack independently blocks workspace-to-workspace TCP access.</p><h2 id="bridge-mtls-material" tabindex="-1">Bridge mTLS Material <a class="header-anchor" href="#bridge-mtls-material" aria-label="Permalink to &quot;Bridge mTLS Material&quot;">​</a></h2><p>Generate strict bridge mTLS material with the repository tool instead of hand-writing OpenSSL commands:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">INSTANCE_ID</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uuidgen</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;[:upper:]&#39; &#39;[:lower:]&#39;)&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/gen-bridge-mtls.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -instance-id</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$INSTANCE_ID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/memoh/bridge-mtls</span></span></code></pre></div><p>The <code>mise</code> equivalent is:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mise</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bridge:mtls:gen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -instance-id</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$INSTANCE_ID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/memoh/bridge-mtls</span></span></code></pre></div><p>The generator creates two independent CAs, signs one <code>ClientAuth</code> certificate for the Memoh server, signs one <code>ServerAuth</code> certificate for the workspace bridge, writes only the required leaf keys and CA bundles, and discards both CA private keys. It prints a config snippet like this:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">instance_id = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;11111111-1111-1111-1111-111111111111&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bridge_tls</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mode = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;strict&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">server_dir = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/opt/memoh/bridge-mtls/server&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bridge_dir = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/opt/memoh/bridge-mtls/bridge&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">server_name = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span></code></pre></div><p><code>server_dir</code> is read only by the Memoh server and contains:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>server-client.crt</span></span>
<span class="line"><span>server-client.key</span></span>
<span class="line"><span>bridge-server-ca.crt</span></span></code></pre></div><p><code>bridge_dir</code> is mounted read-only into workspace containers and must contain only:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>bridge-server.crt</span></span>
<span class="line"><span>bridge-server.key</span></span>
<span class="line"><span>server-client-ca.crt</span></span></code></pre></div><p>Do not reuse <code>server_dir</code> for <code>bridge_dir</code>, and do not copy <code>server-client.crt</code> or <code>server-client.key</code> into <code>bridge_dir</code>. Strict mode rejects a shared directory, symlinked shared directory, missing material, or unexpected files in <code>bridge_dir</code> before mounting anything into a workspace.</p><p>If you enable strict bridge mTLS on an existing deployment, recreate or restart all existing workspace containers. Old containers do not have the TLS material mount or <code>BRIDGE_TLS_*</code> environment variables and will fail closed once the server requires mTLS.</p><h2 id="host-requirements" tabindex="-1">Host Requirements <a class="header-anchor" href="#host-requirements" aria-label="Permalink to &quot;Host Requirements&quot;">​</a></h2><ul><li>Linux host with KVM available at <code>/dev/kvm</code>.</li><li>Nested virtualization enabled if the host itself is a VM.</li><li>Docker with Docker Compose v2.</li><li>Kata Containers installed on the host.</li><li><code>curl</code> and <code>jq</code> on the host for the API verifier.</li></ul><p>Default host paths:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MEMOH_KATA_SHIM_PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/opt/kata/bin/containerd-shim-kata-v2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MEMOH_KATA_CONFIG_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/etc/kata-containers</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MEMOH_KATA_SHARE_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/usr/share/kata-containers</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MEMOH_KATA_OPT_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/opt/kata</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MEMOH_KATA_SYSLOG_SOCKET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/run/systemd/journal/dev-log</span></span></code></pre></div><p>If your Kata install uses different paths, export those variables before running the dev or production compose commands. The syslog socket is mounted into the server container as <code>/dev/log</code> so the Kata shim can initialize logging. On non-systemd hosts, set <code>MEMOH_KATA_SYSLOG_SOCKET</code> to the host&#39;s syslog socket path.</p><p>The Dockerized Memoh server runs a nested containerd for workspace containers. The Kata compose overrides therefore set <code>cgroup: host</code> and <code>shm_size: 1gb</code> on the server service. The host cgroup namespace lets the nested Kata runtime create sandbox cgroup controllers, and the larger shared-memory segment avoids QEMU/KVM boot failures caused by Docker&#39;s small default <code>/dev/shm</code>.</p><p>If the Linux/KVM host needs a proxy during Docker image builds, set the build proxy variables before running the Kata compose tasks:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MEMOH_KATA_BUILD_HTTP_PROXY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://172.17.0.1:7890</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MEMOH_KATA_BUILD_HTTPS_PROXY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://172.17.0.1:7890</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MEMOH_KATA_BUILD_NO_PROXY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">127.0.0.1,localhost</span></span></code></pre></div><p>Use a host address that is reachable from Docker build containers. On Linux, <code>localhost</code> inside a Dockerfile <code>RUN</code> step is the build container, not the host.</p><h2 id="development-stack" tabindex="-1">Development Stack <a class="header-anchor" href="#development-stack" aria-label="Permalink to &quot;Development Stack&quot;">​</a></h2><p>Use this on a dedicated Linux/KVM development host:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mise</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kata:runner</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mise</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev:kata</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mise</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev:kata:status</span></span></code></pre></div><p><code>kata:runner</code> is a lightweight readiness check for the runner or development host. It writes <code>tmp/kata-evidence/environment.txt</code>, verifies Docker and Docker Compose are usable, then checks Linux, <code>/dev/kvm</code>, the Kata shim, Kata config, and Kata runtime asset directories before any Memoh stack is started.</p><p><code>dev:kata:status</code> is a lightweight diagnostic for the current dev server. Use it when <code>http://127.0.0.1:18082</code> is already open and you need to check whether the backing server is the Kata dev stack or the normal dev stack. It inspects <code>/ping</code>, the <code>memoh-dev-server</code> container <code>CONFIG_PATH</code>, <code>/dev/kvm</code>, and the Kata shim/config mounts.</p><p><code>container_backend = &quot;containerd&quot;</code> is expected for Kata. The value that proves the workspace runtime is Kata is <code>runtime_backend = &quot;io.containerd.kata.v2&quot;</code> on a bot workspace, or <code>Runtime.Name = &quot;io.containerd.kata.v2&quot;</code> from <code>ctr containers info</code>.</p><h2 id="production-compose" tabindex="-1">Production Compose <a class="header-anchor" href="#production-compose" aria-label="Permalink to &quot;Production Compose&quot;">​</a></h2><p>Use this on a dedicated Linux/KVM host because the root compose file uses fixed container names such as <code>memoh-server</code> and <code>memoh-postgres</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.kata.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span></span></code></pre></div><p>For manual production deployment, copy and edit the Kata config first:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> conf/app.kata.docker.toml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config.kata.toml</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Change admin password, JWT secret, and database password.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MEMOH_CONFIG</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">./config.kata.toml</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.kata.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>After startup, create or recreate a bot workspace and check that the workspace runtime is <code>io.containerd.kata.v2</code>.</p><p>For a direct runtime smoke test, run a small container with the Kata runtime inside the server&#39;s containerd environment:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ctr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> default</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --runtime</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> io.containerd.kata.v2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --snapshotter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> overlayfs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  docker.io/library/alpine:3.22</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  memoh-kata-smoke</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  /bin/sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;printf &quot;runtime-smoke-ok\\n&quot;&#39;</span></span></code></pre></div><p>The expected container runtime name from <code>ctr -n default containers info workspace-&lt;bot-id&gt;</code> is <code>io.containerd.kata.v2</code>.</p><h2 id="github-actions-runner" tabindex="-1">GitHub Actions Runner <a class="header-anchor" href="#github-actions-runner" aria-label="Permalink to &quot;GitHub Actions Runner&quot;">​</a></h2><p>Register the runner with these labels:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>self-hosted, linux, x64, kvm, kata</span></span></code></pre></div><p>On the Linux/KVM host, this command can run the readiness preflight and generate a runner registration script that adds the required <code>kvm,kata</code> labels without writing the short-lived GitHub registration token into the generated file:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/prepare-kata-github-runner.sh</span></span></code></pre></div><p>Set <code>MEMOH_KATA_RUNNER_NAME</code>, <code>MEMOH_KATA_RUNNER_DIR</code>, or <code>MEMOH_KATA_RUNNER_SCRIPT</code> to override the generated runner name, install directory, or output script. The <code>mise</code> equivalent is <code>mise run kata:github:runner</code>. The generated registration script rechecks Linux, x86_64/amd64, <code>/dev/kvm</code>, Docker Compose, and the Kata shim/config paths before registering the runner, so a copied script cannot silently register the wrong host with the <code>kvm,kata</code> labels.</p><p>To check a newly registered runner without starting the Memoh stack, run the workflow manually with <code>run_runner_readiness=true</code>. This runs only <code>scripts/check-kata-runner-ready.sh</code> and uploads a <code>kata-runner-readiness</code> artifact containing the environment summary.</p><p>Once a runner with the required labels is registered, this command can dispatch the readiness workflow from the PR branch, wait for it to finish, and audit the PR checks:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/run-kata-github-e2e.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">pr-numbe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>The <code>mise</code> equivalent is <code>mise run kata:github:readiness -- &lt;pr-number&gt;</code>. Because GitHub requires <code>workflow_dispatch</code> workflows to be registered before they can be manually run, this command checks that the workflow is available before dispatching.</p><p>To audit whether a PR head has completed runner readiness verification, run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/audit-kata-github-verification.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">pr-numbe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>Use <code>mise run kata:github -- &lt;pr-number&gt;</code> as the task equivalent.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><ul><li><code>Kata validation requires a Linux host with KVM</code>: run the E2E on a Linux host with KVM. Docker Desktop is not enough.</li><li><code>/dev/kvm is missing</code>: enable KVM or nested virtualization, then make sure Docker can pass <code>/dev/kvm</code> through.</li><li><code>Kata shim not found</code>: set <code>MEMOH_KATA_SHIM_PATH</code> to the host <code>containerd-shim-kata-v2</code> path.</li><li>Missing paths from <code>configuration.toml</code>: mount the referenced Kata assets or set <code>MEMOH_KATA_SHARE_DIR</code> / <code>MEMOH_KATA_OPT_DIR</code> to the correct host paths.</li><li>Runtime mismatch in <code>ctr containers info</code>: confirm the server config uses <code>runtime_type = &quot;io.containerd.kata.v2&quot;</code> and that the Kata compose override is included.</li><li>Direct Kata smoke test passes but a bot workspace cannot start: check the server logs for Kata shim, cgroup, <code>/dev/log</code>, <code>/dev/kvm</code>, or bridge connection errors.</li></ul>`,60)])])}const g=e(n,[["render",o]]);export{k as __pageData,g as default};
